src/main/java/org/apache/maven/scm/provider/svn/svnjava/command/list/SvnJavaListCommand.java
public class SvnJavaListCommand
    extends AbstractListCommand
    implements SvnCommand
{

    @Override
    public ScmResult executeCommand( ScmProviderRepository repository, ScmFileSet fileSet,
                                     CommandParameters parameters )
        throws ScmException
    {
        boolean recursive = parameters == null ? false : parameters.getBoolean( CommandParameter.RECURSIVE );
        ScmVersion scmVersion =
            parameters == null ? null : parameters.getScmVersion( CommandParameter.SCM_VERSION, null );
        return executeListCommand( repository, fileSet, recursive, scmVersion );
    }

    @Override
    protected ListScmResult executeListCommand( ScmProviderRepository scmProviderRepository, ScmFileSet scmFileSet,
                                                boolean recursive, ScmVersion version )
        throws ScmException
    {
        SvnJavaScmProviderRepository javaRepo = (SvnJavaScmProviderRepository) scmProviderRepository;

        String url = javaRepo.getUrl();

        SVNRevision revision = SVNRevision.HEAD;

        if ( version != null && StringUtils.isNotEmpty( version.getName() ) )
        {
            if ( version instanceof ScmTag )
            {
                url = SvnTagBranchUtils.resolveTagUrl( javaRepo, (ScmTag) version );
            }
            else if ( version instanceof ScmBranch )
            {
                url = SvnTagBranchUtils.resolveBranchUrl( javaRepo, (ScmBranch) version );
            }
            else if ( version instanceof ScmRevision )
            {
                try
                {
                    revision = SVNRevision.create( Long.parseLong( ( (ScmRevision) version ).getName() ) );
                }
                catch ( NumberFormatException exc )
                {
                    return new ListScmResult( SvnJavaScmProvider.COMMAND_LINE,
                                              "SVN checkout failed. Wrong format of revision number.", null, false );
                }
            }
        }

        if ( url != null )
        {
            url = SvnCommandUtils.fixUrl( url, javaRepo.getUser() );
        }
        ListEntryHandler listEntryHandler = new ListEntryHandler();

        /*
        SVNURL url,
        SVNRevision pegRevision,
        SVNRevision revision,
        boolean fetchLocks,
        SVNDepth depth,
        int entryFields,
        ISVNDirEntryHandler handler
        */

        try
        {
            javaRepo.getClientManager().getLogClient().doList(
                url == null ? javaRepo.getSvnUrl() : SVNURL.parseURIEncoded( url ), revision, revision, true,
                // boolean fetchLocks,
                SVNDepth.IMMEDIATES, 0, listEntryHandler );
        }
        catch ( SVNException e )
        {
            throw new ScmException( "Error while executing svn list.", e );
        }

        List<ScmFile> scmFiles = new ArrayList<ScmFile>( listEntryHandler.relativePaths.size() );

        for ( String path : listEntryHandler.relativePaths )
        {
            scmFiles.add( new ScmFile( path, ScmFileStatus.CHECKED_IN ) );
        }

        ListScmResult listScmResult = new ListScmResult( scmFiles, new ScmResult( null, null, null, false ) );
        return listScmResult;

    }

    private static class ListEntryHandler
        implements ISVNDirEntryHandler
    {
        private List<String> relativePaths = new ArrayList<String>();

        public void handleDirEntry( SVNDirEntry svnDirEntry )
            throws SVNException
        {
            if ( StringUtils.isNotEmpty( svnDirEntry.getRelativePath() ) )
            {
                relativePaths.add( svnDirEntry.getRelativePath() );
            }
        }
    }
}
src/main/java/org/apache/maven/scm/provider/svn/svnjava/command/changelog/SvnJavaChangeLogCommand.java
public class SvnJavaChangeLogCommand
    extends AbstractChangeLogCommand
    implements SvnCommand
{
    /**
     * {@inheritDoc}
     */
    protected ChangeLogScmResult executeChangeLogCommand( ScmProviderRepository repository, ScmFileSet fileSet,
                                                          ScmVersion startVersion, ScmVersion endVersion,
                                                          String datePattern )
        throws ScmException
    {
        throw new UnsupportedOperationException( "executeChangeLogCommand( ScmProviderRepository repository, "
                                                     + "ScmFileSet fileSet, ScmVersion startVersion, ScmVersion endVersion, String datePattern ) is not "
                                                     + "implemented" );
    }

    /**
     * {@inheritDoc}
     */
    protected ChangeLogScmResult executeChangeLogCommand( ScmProviderRepository repo, ScmFileSet fileSet,
                                                          Date startDate, Date endDate, ScmBranch branch,
                                                          String datePattern )
        throws ScmException
    {
        SvnJavaScmProviderRepository javaRepo = (SvnJavaScmProviderRepository) repo;

        SVNRevision startRevision = ( startDate != null ) ? SVNRevision.create( startDate ) : SVNRevision.UNDEFINED;
        SVNRevision endRevision = ( endDate != null ) ? SVNRevision.create( endDate ) : SVNRevision.HEAD;

        try
        {
            SVNURL url = javaRepo.getSvnUrl();

            if ( branch != null )
            {
                url = SVNURL.parseURIEncoded( SvnTagBranchUtils.resolveBranchUrl( javaRepo, branch ) );
            }

            ChangeLogHandler handler = new ChangeLogHandler( startDate, endDate );

            SvnJavaUtil.changelog( javaRepo.getClientManager(), url, startRevision, endRevision, true, // stopOnCopy
                                   true, // reportPaths
                                   handler );

            return new ChangeLogScmResult( SvnJavaScmProvider.COMMAND_LINE, handler.getChangeSets() );
        }
        catch ( SVNException e )
        {
            return new ChangeLogScmResult( SvnJavaScmProvider.COMMAND_LINE, "SVN Changelog failed.", e.getMessage(),
                                           false );
        }
    }

    // ----------------------------------------------------------------------
    //
    // ----------------------------------------------------------------------

    protected static class ChangeLogHandler
        implements ISVNLogEntryHandler
    {
        private ChangeLogSet changeLogSet;

        private List<ChangeSet> changeSets = new ArrayList<ChangeSet>();

        public ChangeLogHandler( Date startDate, Date endDate )
        {
            changeLogSet = new ChangeLogSet( startDate, endDate );
        }

        public void handleLogEntry( SVNLogEntry logEntry )
            throws SVNException
        {
            List<ChangeFile> changedFiles = new ArrayList<ChangeFile>();

            for ( String changedPath : logEntry.getChangedPaths().keySet() )
            {
                changedFiles.add( new ChangeFile( changedPath, Long.toString( logEntry.getRevision() ) ) );
            }

            SvnChangeSet changeSet =
                new SvnChangeSet( logEntry.getDate(), logEntry.getMessage(), logEntry.getAuthor(), changedFiles );
            changeSet.setRevision( Long.toString( logEntry.getRevision() ) );
            changeSets.add( changeSet );
        }

        public ChangeLogSet getChangeSets()
        {
            changeLogSet.setChangeSets( changeSets );

            return changeLogSet;
        }
    }
}
