public class SvnJavaBranchCommand
    extends AbstractBranchCommand
    implements SvnCommand
{

    /**
     * @see org.apache.maven.scm.command.branch.AbstractBranchCommand#executeBranchCommand(org.apache.maven.scm.provider.ScmProviderRepository, org.apache.maven.scm.ScmFileSet, java.lang.String, java.lang.String)
     */
    protected ScmResult executeBranchCommand( ScmProviderRepository repo, ScmFileSet fileSet, String branch,
                                              ScmBranchParameters scmBranchParameters )
        throws ScmException
    {
        if ( branch == null || StringUtils.isEmpty( branch.trim() ) )
        {
            throw new ScmException( "branch name must be specified" );
        }

        if ( !fileSet.getFileList().isEmpty() )
        {
            throw new ScmException( "This provider doesn't support branching subsets of a directory" );
        }
        SvnScmProviderRepository repository = (SvnScmProviderRepository) repo;

        SvnJavaScmProviderRepository javaRepo = (SvnJavaScmProviderRepository) repo;
        try
        {

            SVNURL destURL =
                SVNURL.parseURIEncoded( SvnTagBranchUtils.resolveBranchUrl( repository, new ScmBranch( branch ) ) );

            String message = "[maven-scm] copy for branch " + branch;
            if ( scmBranchParameters != null )
            {
                message = scmBranchParameters.getMessage();
            }

            SVNCommitInfo info;
            if ( scmBranchParameters != null && scmBranchParameters.isRemoteBranching() )
            {
                info = SvnJavaUtil.copy( javaRepo.getClientManager(), javaRepo.getSvnUrl(), destURL, false, message,
                                         null );
            }
            else
            {
                info = SvnJavaUtil.copy( javaRepo.getClientManager(), fileSet.getBasedir(), destURL, false, message,
                                         null );
            }

            if ( info.getErrorMessage() != null )
            {
                return new TagScmResult( SvnJavaScmProvider.COMMAND_LINE, "SVN tag failed.",
                                         info.getErrorMessage().getMessage(), false );
            }
            List<ScmFile> fileList = new ArrayList<ScmFile>();

            List<File> files = null;

            try
            {
                @SuppressWarnings( "unchecked" ) List<File> listFiles =
                    FileUtils.getFiles( fileSet.getBasedir(), "**", "**/.svn/**", false );
                files = listFiles;
            }
            catch ( IOException e )
            {
                throw new ScmException( "Error while executing command.", e );
            }

            for ( File f : files )
            {
                fileList.add( new ScmFile( f.getPath(), ScmFileStatus.TAGGED ) );
            }
            return new BranchScmResult( SvnJavaScmProvider.COMMAND_LINE, fileList );
        }
        catch ( SVNException e )
        {
            return new BranchScmResult( SvnJavaScmProvider.COMMAND_LINE, "SVN tag failed.", e.getMessage(), false );
        }
    }

    /**
     * {@inheritDoc}
     */
    public ScmResult executeBranchCommand( ScmProviderRepository repo, ScmFileSet fileSet, String branch,
                                           String message )
        throws ScmException
    {
        ScmBranchParameters scmBranchParameters = new ScmBranchParameters( message );
        return executeBranchCommand( repo, fileSet, branch, scmBranchParameters );
    }
}
src/main/java/org/apache/maven/scm/provider/svn/svnjava/command/tag/SvnTagCommand.java
public class SvnTagCommand
    extends AbstractTagCommand
    implements SvnCommand
{
    /**
     * {@inheritDoc}
     */
    protected ScmResult executeTagCommand( ScmProviderRepository repo, ScmFileSet fileSet, String tag, String message )
        throws ScmException
    {
        return executeTagCommand( repo, fileSet, tag, new ScmTagParameters( message ) );
    }

    protected ScmResult executeTagCommand( ScmProviderRepository repo, ScmFileSet fileSet, String tag,
                                           ScmTagParameters scmTagParameters )
        throws ScmException
    {
        if ( tag == null )
        {
            throw new ScmException( "tag must be specified" );
        }

        if ( !fileSet.getFileList().isEmpty() )
        {
            throw new ScmException( "This provider doesn't support tagging subsets of a directory" );
        }

        if ( getLogger().isInfoEnabled() )
        {
            getLogger().info( "SVN checkout directory: " + fileSet.getBasedir().getAbsolutePath() );
        }

        SvnScmProviderRepository repository = (SvnScmProviderRepository) repo;

        SvnJavaScmProviderRepository javaRepo = (SvnJavaScmProviderRepository) repo;

        try
        {
            SVNURL destURL = SVNURL.parseURIEncoded( SvnTagBranchUtils.resolveTagUrl( repository, new ScmTag( tag ) ) );

            String message = "[maven-scm] copy for tag " + tag;

            if ( StringUtils.isNotBlank( scmTagParameters.getMessage() ) )
            {
                message = scmTagParameters.getMessage();
            }

            SVNCommitInfo info;
            if ( scmTagParameters != null && scmTagParameters.isRemoteTagging() )
            {
                info = SvnJavaUtil.copy( javaRepo.getClientManager(), javaRepo.getSvnUrl(), destURL, false, message,
                                         scmTagParameters.getScmRevision() );
            }
            else
            {
                info = SvnJavaUtil.copy( javaRepo.getClientManager(), fileSet.getBasedir(), destURL, false, message,
                                         scmTagParameters.getScmRevision() );
            }

            if ( info.getErrorMessage() != null )
            {
                return new TagScmResult( SvnJavaScmProvider.COMMAND_LINE, "SVN tag failed.",
                                         info.getErrorMessage().getMessage(), false );
            }

            // The copy command doesn't return a list of files that were tagged,
            // so manually build the list from the contents of the fileSet.getBaseDir.
            List<ScmFile> fileList = new ArrayList<ScmFile>();
            List<File> files = null;
            try
            {
                @SuppressWarnings( "unchecked" ) List<File> list =
                    FileUtils.getFiles( fileSet.getBasedir(), "**", "**/.svn/**", false );
                files = list;
            }
            catch ( IOException e )
            {
                throw new ScmException( "Error while building list of tagged files.", e );
            }

            for ( Iterator<File> i = files.iterator(); i.hasNext(); )
            {
                File f = i.next();
                fileList.add( new ScmFile( f.getPath(), ScmFileStatus.TAGGED ) );
            }

            return new TagScmResult( SvnJavaScmProvider.COMMAND_LINE, fileList );
        }
        catch ( SVNException e )
        {
            return new TagScmResult( SvnJavaScmProvider.COMMAND_LINE, "SVN tag failed.", e.getMessage(), false );
        }
    }

}
src/main/java/org/apache/maven/scm/provider/svn/svnjava/command/mkdir/SvnJavaMkdirCommand.java
public class SvnJavaMkdirCommand
    extends AbstractMkdirCommand
    implements SvnCommand
{

    /**
     * @see org.apache.maven.scm.command.mkdir.AbstractMkdirCommand#executeMkdirCommand(ScmProviderRepository, ScmFileSet, String, boolean)
     */
    @Override
    protected MkdirScmResult executeMkdirCommand( ScmProviderRepository repository, ScmFileSet fileSet, String message,
                                                  boolean createInLocal )
        throws ScmException
    {
        SvnJavaScmProviderRepository javaRepo = (SvnJavaScmProviderRepository) repository;
        Iterator<File> it = fileSet.getFileList().iterator();
        String dirPath = it.next().getPath();
        // replacing \ with / for windauze
        if ( dirPath != null && Os.isFamily( Os.FAMILY_DOS ) )
        {
            dirPath = StringUtils.replace( dirPath, "\\", "/" );
        }
        String url = javaRepo.getUrl() + "/" + dirPath;
        if ( createInLocal )
        {
            url = dirPath;
        }
        List<SVNURL> svnurls = new ArrayList<SVNURL>( 1 );
        try
        {
            svnurls.add( SVNURL.parseURIEncoded( url ) );

            SVNCommitInfo commitInfo =
                SvnJavaUtil.mkdir( javaRepo.getClientManager(), svnurls.toArray( new SVNURL[svnurls.size()] ),
                                   message );
            ScmResult scmResult = new ScmResult( null, null, null, true );

            return new MkdirScmResult( Long.toString( commitInfo.getNewRevision() ), scmResult );
        }
        catch ( SVNException e )
        {
            throw new ScmException( e.getMessage(), e );
        }
    }

}
