src/main/java/org/apache/maven/scm/provider/svn/svnjava/command/update/SvnJavaUpdateCommand.java
public class SvnJavaUpdateCommand
    extends AbstractUpdateCommand
    implements SvnCommand
{
    /**
     * {@inheritDoc}
     */
    protected UpdateScmResult executeUpdateCommand( ScmProviderRepository repo, ScmFileSet fileSet, ScmVersion tag )
        throws ScmException
    {
        SvnScmProviderRepository repository = (SvnScmProviderRepository) repo;

        if ( getLogger().isInfoEnabled() )
        {
            getLogger().info( "SVN update directory: " + fileSet.getBasedir().getAbsolutePath() );
        }

        SvnJavaScmProviderRepository javaRepo = (SvnJavaScmProviderRepository) repo;

        try
        {
            ScmFileEventHandler handler = new ScmFileEventHandler( getLogger(), fileSet.getBasedir() );

            SVNUpdateClient updateClient = javaRepo.getClientManager().getUpdateClient();

            updateClient.setEventHandler( handler );

            long revision = 0;

            if ( tag == null || SvnTagBranchUtils.isRevisionSpecifier( tag ) )
            {
                SVNRevision rev = ( tag == null ? SVNRevision.parse( "" ) : SVNRevision.parse( tag.getName() ) );
                revision = SvnJavaUtil.update( updateClient, fileSet.getBasedir(), rev, true );
            }
            else
            {
                // The tag specified does not appear to be numeric, so assume it refers
                // to a branch/tag url and perform a switch operation rather than update
                revision = SvnJavaUtil.switchToURL( javaRepo.getClientManager(), fileSet.getBasedir(),
                                                    SVNURL.parseURIEncoded( SvnTagBranchUtils.resolveTagUrl( repository,
                                                                                                             new ScmTag(
                                                                                                                 tag.getName() ) ) ),
                                                    SVNRevision.HEAD, true );
            }

            return new UpdateScmResultWithRevision( SvnJavaScmProvider.COMMAND_LINE, handler.getFiles(),
                                                    Long.toString( revision ) );
        }
        catch ( SVNException e )
        {
            return new UpdateScmResultWithRevision( SvnJavaScmProvider.COMMAND_LINE, "SVN update failed.",
                                                    e.getMessage(), Long.toString( -1 ), false );
        }
        finally
        {
            javaRepo.getClientManager().getUpdateClient().setEventHandler( null );
        }
    }

    /**
     * {@inheritDoc}
     */
    protected ChangeLogCommand getChangeLogCommand()
    {
        SvnJavaChangeLogCommand command = new SvnJavaChangeLogCommand();

        command.setLogger( getLogger() );

        return command;
    }
}
src/main/java/org/apache/maven/scm/provider/svn/svnjava/command/diff/SvnJavaDiffCommand.java
public class SvnJavaDiffCommand
    extends AbstractDiffCommand
    implements SvnCommand
{
    /**
     * {@inheritDoc}
     */
    protected DiffScmResult executeDiffCommand( ScmProviderRepository repo, ScmFileSet fileSet,
                                                ScmVersion startRevision, ScmVersion endRevision )
        throws ScmException
    {
        if ( getLogger().isInfoEnabled() )
        {
            getLogger().info( "SVN diff directory: " + fileSet.getBasedir().getAbsolutePath() );
        }

        SvnJavaScmProviderRepository javaRepo = (SvnJavaScmProviderRepository) repo;

        ScmFileEventHandler handler = new ScmFileEventHandler( getLogger(), fileSet.getBasedir() );

        try
        {
            javaRepo.getClientManager().getDiffClient().setEventHandler( handler );

            SVNRevision start =
                ( startRevision == null ) ? SVNRevision.COMMITTED : SVNRevision.parse( startRevision.getName() );
            SVNRevision end =
                ( endRevision == null ) ? SVNRevision.WORKING : SVNRevision.parse( endRevision.getName() );

            ByteArrayOutputStream out =
                SvnJavaUtil.diff( javaRepo.getClientManager(), fileSet.getBasedir(), start, end );

            SvnDiffConsumer consumer = new SvnDiffConsumer( getLogger(), fileSet.getBasedir() );

            ByteArrayInputStream bis = new ByteArrayInputStream( out.toByteArray() );

            BufferedReader in = new BufferedReader( new InputStreamReader( bis ) );

            String line = in.readLine();
            while ( line != null )
            {
                consumer.consumeLine( line );

                line = in.readLine();
            }

            return new DiffScmResult( SvnJavaScmProvider.COMMAND_LINE, consumer.getChangedFiles(),
                                      consumer.getDifferences(), consumer.getPatch() );
        }
        catch ( IOException e )
        {
            return new DiffScmResult( SvnJavaScmProvider.COMMAND_LINE, "SVN diff failed.", e.getMessage(), false );
        }
        catch ( SVNException e )
        {
            return new DiffScmResult( SvnJavaScmProvider.COMMAND_LINE, "SVN diff failed.", e.getMessage(), false );
        }
        finally
        {
            javaRepo.getClientManager().getDiffClient().setEventHandler( null );
        }
    }
}
src/main/java/org/apache/maven/scm/provider/svn/svnjava/command/checkin/SvnJavaCheckInCommand.java
public class SvnJavaCheckInCommand
    extends AbstractCheckInCommand
    implements SvnCommand
{
    /**
     * {@inheritDoc}
     */
    protected CheckInScmResult executeCheckInCommand( ScmProviderRepository repo, ScmFileSet fileSet, String message,
                                                      ScmVersion tag )
        throws ScmException
    {
        if ( getLogger().isInfoEnabled() )
        {
            getLogger().info( "SVN commit directory: " + fileSet.getBasedir().getAbsolutePath() );
        }

        SvnJavaScmProviderRepository javaRepo = (SvnJavaScmProviderRepository) repo;

        CommitHandler handler = new CommitHandler( fileSet.getBasedir().getAbsolutePath() );

        SVNCommitClient svnCommitClient = javaRepo.getClientManager().getCommitClient();

        svnCommitClient.setCommitHandler( handler );

        try
        {
            List<File> tmpPaths = fileSet.getFileList();
            List<File> paths;
            if ( tmpPaths == null || tmpPaths.isEmpty() )
            {
                paths = new ArrayList<File>( 1 );
                paths.add( fileSet.getBasedir() );
            }
            else
            {
                paths = new ArrayList<File>( tmpPaths.size() );
                for ( File f : tmpPaths )
                {
                    if ( f.isAbsolute() )
                    {
                        paths.add( f );
                    }
                    else
                    {
                        paths.add( new File( fileSet.getBasedir(), f.toString() ) );
                    }
                }
            }

            SVNCommitInfo svnCommitInfo =
                SvnJavaUtil.commit( svnCommitClient, paths.toArray( new File[paths.size()] ), false, message, true );

            List<ScmFile> files = new ArrayList<ScmFile>();
            for ( String filePath : handler.getFiles() )
            {
                files.add( new ScmFile( filePath, ScmFileStatus.CHECKED_IN ) );
            }

            return new CheckInScmResult( SvnJavaScmProvider.COMMAND_LINE, files,
                                         Long.toString( svnCommitInfo.getNewRevision() ) );
        }
        catch ( SVNException e )
        {
            return new CheckInScmResult( SvnJavaScmProvider.COMMAND_LINE, "SVN commit failed.", e.getMessage(), false );
        }
        finally
        {
            javaRepo.getClientManager().getCommitClient().setEventHandler( null );
        }
    }

    public static class CommitHandler
        implements ISVNCommitHandler
    {
        private List<String> files = new ArrayList<String>();

        private String baseDirectory;

        public CommitHandler( String baseDirectory )
        {
            this.baseDirectory = FilenameUtils.separatorsToUnix( baseDirectory );
            if ( !StringUtils.endsWith( this.baseDirectory, "/" ) )
            {
                this.baseDirectory += "/";
            }
        }

        public String getCommitMessage( String message, SVNCommitItem[] commitItems )
            throws SVNException
        {
            if ( commitItems != null )
            {

                {
                    for ( SVNCommitItem commitItem : commitItems )
                    {
                        if ( commitItem.getFile().isFile() )
                        {
                            String path =
                                StringUtils.removeStartIgnoreCase( commitItem.getFile().getPath(), baseDirectory );

                            files.add( path );
                        }
                    }
                }
            }
            return message;
        }

        public SVNProperties getRevisionProperties( String arg0, SVNCommitItem[] arg1, SVNProperties svnProperties )
            throws SVNException
        {
            return svnProperties;
        }

        public List<String> getFiles()
        {
            return files;
        }

    }
}
src/main/java/org/apache/maven/scm/provider/svn/svnjava/command/blame/SvnJavaBlameCommand.java
public class SvnJavaBlameCommand
    extends AbstractBlameCommand
    implements SvnCommand
{

    /**
     * @see org.apache.maven.scm.command.blame.AbstractBlameCommand#executeBlameCommand(org.apache.maven.scm.provider.ScmProviderRepository,
     *      org.apache.maven.scm.ScmFileSet, java.lang.String)
     */
    @Override
    public BlameScmResult executeBlameCommand( ScmProviderRepository repo, ScmFileSet workingDirectory,
                                               String filename )
        throws ScmException
    {
        try
        {
            SvnJavaScmProviderRepository javaRepo = (SvnJavaScmProviderRepository) repo;
            javaRepo.getClientManager();
            AnnotationHandler handler = new AnnotationHandler();
            SvnJavaUtil.blame( javaRepo.getClientManager(), new File( workingDirectory.getBasedir(), filename ),
                               handler );
            return new BlameScmResult( "", handler.lines );
        }
        catch ( SVNException e )
        {
            throw new ScmException( e.getMessage(), e );
        }
    }

    private static class AnnotationHandler
        implements ISVNAnnotateHandler
    {

        private List<BlameLine> lines = new ArrayList<BlameLine>();

        public void handleEOF()
        {
            // no op
        }

        /**
         * @deprecated
         */
        public void handleLine( Date arg0, long arg1, String arg2, String arg3 )
            throws SVNException
        {
            // no op
        }

        public void handleLine( Date date, long revision, String author, String line, Date mergedDate,
                                long mergedRevision, String mergedAuthor, String mergedPath, int lineNumber )
            throws SVNException
        {
            BlameLine blameLine = new BlameLine( date, Long.toString( revision ), author );
            if ( lines.size() > lineNumber )
            {
                lines.set( lineNumber, blameLine );
            }
            else
            {
                lines.add( blameLine );
            }
        }

        public boolean handleRevision( Date arg0, long arg1, String arg2, File arg3 )
            throws SVNException
        {
            return true;
        }

    }

}
src/main/java/org/apache/maven/scm/provider/svn/svnjava/command/add/SvnJavaAddCommand.java
public class SvnJavaAddCommand
    extends AbstractAddCommand
    implements SvnCommand
{

    @Override
    protected ScmResult executeCommand( ScmProviderRepository repository, ScmFileSet fileSet,
                                        CommandParameters parameters )
        throws ScmException
    {
        if ( fileSet.getFileList().isEmpty() )
        {
            throw new ScmException( "You must provide at least one file/directory to add" );
        }

        final List<ScmFile> filesAdded = new ArrayList<ScmFile>();

        SvnJavaScmProviderRepository javaRepo = (SvnJavaScmProviderRepository) repository;

        SVNClientManager clientManager = javaRepo.getClientManager();

        try
        {
            clientManager.getWCClient().setEventHandler( new ISVNEventHandler()
            {

                public void handleEvent( SVNEvent event, double progress )
                {
                    if ( event.getAction() == SVNEventAction.ADD )
                    {
                        filesAdded.add( new ScmFile( event.getFile().getPath(), ScmFileStatus.ADDED ) );
                    }
                }

                public void checkCancelled()
                    throws SVNCancelException
                {
                    // null
                }
            } );

            for ( File file : fileSet.getFileList() )
            {
                File fileToAdd = new File( fileSet.getBasedir(), file.toString() );

                if ( getLogger().isDebugEnabled() )
                {
                    getLogger().debug( "SVN adding file: " + fileToAdd.getAbsolutePath() );
                }

                boolean forceAdd = parameters.getBoolean( CommandParameter.FORCE_ADD, false );
                SvnJavaUtil.add( clientManager, fileToAdd, false, forceAdd );
            }
        }
        catch ( SVNException e )
        {
            return new AddScmResult( SvnJavaScmProvider.COMMAND_LINE, "The svn operation failed.", e.getMessage(),
                                     false );
        }
        finally
        {
            clientManager.getWCClient().setEventHandler( null );
        }

        return new AddScmResult( null, filesAdded );
    }

    /**
     * {@inheritDoc}
     */
    protected ScmResult executeAddCommand( ScmProviderRepository repository, ScmFileSet fileSet, String message,
                                           boolean binary )
        throws ScmException
    {
        CommandParameters commandParameters = new CommandParameters();
        commandParameters.setString( CommandParameter.MESSAGE, message );
        return executeCommand( repository, fileSet, commandParameters );
    }
}
src/main/java/org/apache/maven/scm/provider/svn/svnjava/command/remoteinfo/SvnJavaRemoteInfoCommand.java
public class SvnJavaRemoteInfoCommand
    extends AbstractRemoteInfoCommand
    implements SvnCommand
{
    @Override
    public RemoteInfoScmResult executeRemoteInfoCommand( ScmProviderRepository repository, ScmFileSet fileSet,
                                                         CommandParameters parameters )
        throws ScmException
    {
        SvnJavaScmProviderRepository javaRepo = (SvnJavaScmProviderRepository) repository;

        String url = ( (SvnScmProviderRepository) repository ).getUrl();
        // use a default svn layout, url is here http://svn.apache.org/repos/asf/maven/maven-3/trunk
        // so as we presume we have good users using standard svn layout, we calculate tags and branches url
        String baseUrl = StringUtils.endsWith( url, "/" )
            ? StringUtils.substringAfter( StringUtils.removeEnd( url, "/" ), "/" )
            : StringUtils.substringBeforeLast( url, "/" );

        RemoteInfoScmResult remoteInfoScmResult = new RemoteInfoScmResult( null, null, null, true );

        try
        {

            DirEntryHandler dirEntryHandler = new DirEntryHandler( baseUrl );
            javaRepo.getClientManager().getLogClient().doList( SVNURL.parseURIEncoded( baseUrl + "/tags" ),
                                                               SVNRevision.HEAD, SVNRevision.HEAD, false, false,
                                                               dirEntryHandler );
            remoteInfoScmResult.setTags( dirEntryHandler.infos );
        }
        catch ( SVNException e )
        {
            return new RemoteInfoScmResult( null, e.getMessage(), null, false );
        }

        try
        {

            DirEntryHandler dirEntryHandler = new DirEntryHandler( baseUrl );
            javaRepo.getClientManager().getLogClient().doList( SVNURL.parseURIEncoded( baseUrl + "/branches" ),
                                                               SVNRevision.HEAD, SVNRevision.HEAD, false, false,
                                                               dirEntryHandler );
            remoteInfoScmResult.setBranches( dirEntryHandler.infos );
        }
        catch ( SVNException e )
        {
            return new RemoteInfoScmResult( null, e.getMessage(), null, false );
        }

        return remoteInfoScmResult;

    }

    public boolean remoteUrlExist( ScmProviderRepository repository, CommandParameters parameters )
        throws ScmException
    {
        SvnJavaScmProviderRepository javaRepo = (SvnJavaScmProviderRepository) repository;

        String url = ( (SvnScmProviderRepository) repository ).getUrl();

        try
        {

            javaRepo.getClientManager().getWCClient().doInfo( SVNURL.parseURIEncoded( url ), SVNRevision.HEAD,
                                                              SVNRevision.HEAD, SVNDepth.EMPTY, new ISVNInfoHandler()
            {
                public void handleInfo( SVNInfo svnInfo )
                    throws SVNException
                {
                    svnInfo.getAuthor();
                }
            } );
        }
        catch ( SVNException e )
        {
            if ( e.getMessage().indexOf( "E170000" ) > -1 )
            {
                return false;
            }
            throw new ScmException( e.getMessage(), e );
        }
        return true;
    }

    public static class DirEntryHandler
        implements ISVNDirEntryHandler
    {
        String url;

        Map<String, String> infos = new HashMap<String, String>();

        DirEntryHandler( String url )
        {
            this.url = url;
        }

        public void handleDirEntry( SVNDirEntry svnDirEntry )
            throws SVNException
        {
            infos.put( svnDirEntry.getName(), svnDirEntry.getURL().toString() );
        }
    }
}
src/main/java/org/apache/maven/scm/provider/svn/svnjava/command/checkout/SvnJavaCheckOutCommand.java
public class SvnJavaCheckOutCommand
    extends AbstractCheckOutCommand
    implements SvnCommand
{
    /**
     * {@inheritDoc}
     */
    protected CheckOutScmResult executeCheckOutCommand( ScmProviderRepository repo, ScmFileSet fileSet,
                                                        ScmVersion version, boolean recursive )
        throws ScmException
    {
        if ( getLogger().isInfoEnabled() )
        {
            getLogger().info( "SVN checkout directory: " + fileSet.getBasedir().getAbsolutePath() );
        }

        SvnScmProviderRepository repository = (SvnScmProviderRepository) repo;

        String url = repository.getUrl();

        SVNRevision revision = SVNRevision.HEAD;

        if ( version != null && StringUtils.isNotEmpty( version.getName() ) )
        {
            if ( version instanceof ScmTag )
            {
                url = SvnTagBranchUtils.resolveTagUrl( repository, (ScmTag) version );
            }
            else if ( version instanceof ScmBranch )
            {
                url = SvnTagBranchUtils.resolveBranchUrl( repository, (ScmBranch) version );
            }
            else if ( version instanceof ScmRevision )
            {
                try
                {
                    revision = SVNRevision.create( Long.parseLong( ( (ScmRevision) version ).getName() ) );
                }
                catch ( NumberFormatException exc )
                {
                    return new CheckOutScmResult( SvnJavaScmProvider.COMMAND_LINE,
                                                  "SVN checkout failed. Wrong format of revision number.", null,
                                                  false );
                }
            }
        }

        url = SvnCommandUtils.fixUrl( url, repository.getUser() );

        SvnJavaScmProviderRepository javaRepo = (SvnJavaScmProviderRepository) repo;

        ScmFileEventHandler handler = new ScmFileEventHandler( getLogger(), fileSet.getBasedir() );
        SVNUpdateClient updateClient = javaRepo.getClientManager().getUpdateClient();
        updateClient.setEventHandler( handler );

        try
        {
            SvnJavaUtil.checkout( updateClient, SVNURL.parseURIEncoded( url ), revision, fileSet.getBasedir(), true );

            return new CheckOutScmResult( SvnJavaScmProvider.COMMAND_LINE, handler.getFiles() );
        }
        catch ( SVNException e )
        {
            return new CheckOutScmResult( SvnJavaScmProvider.COMMAND_LINE, "SVN checkout failed.", e.getMessage(),
                                          false );
        }
        finally
        {
            javaRepo.getClientManager().getUpdateClient().setEventHandler( null );
        }
    }
