    /**
     * Enables access of files in this container via the Content Delivery
     * Network.
     *
     * @param name The name of the container to enable
     * @param ttl How long the CDN can use the content before checking for an
     * update. A negative value will result in this not being changed.
     * @param enabled True if this container should be accessible, false
     * otherwise
     * @param retainLogs True if cdn access logs should be kept for this
     * container, false otherwise
     * @return The CDN Url of the container
     * @throws IOException There was an IO error doing network communication
     * @throws HttpException There was an error with the http protocol
     * @throws FilesException There was an error talking to the CDN Service
     */
    /*
     * @param referrerAcl Unused for now
     * 
     * @param userAgentACL Unused for now
     */
    private String cdnUpdateContainer(String name, int ttl, boolean enabled,
            String referrerAcl, String userAgentACL, boolean retainLogs)
            throws IOException, HttpException, FilesException {
        String returnValue = null;
        if (this.isLoggedin()) {
            if (isValidContainerName(name)) {
                HttpPost method = null;
                try {
                    method = new HttpPost(cdnManagementURL + "/"
                            + sanitizeForURI(name));

                    method.getParams().setIntParameter("http.socket.timeout",
                            connectionTimeOut);
                    method.setHeader(FilesConstants.X_AUTH_TOKEN, authToken);
                    // TTL
                    if (ttl > 0) {
                        method.setHeader(FilesConstants.X_CDN_TTL,
                                Integer.toString(ttl));
                    }
                    // Enabled
                    method.setHeader(FilesConstants.X_CDN_ENABLED,
                            Boolean.toString(enabled));

                    // Log Retention
                    method.setHeader(FilesConstants.X_CDN_RETAIN_LOGS,
                            Boolean.toString(retainLogs));

                    // Referrer ACL
                    if (referrerAcl != null) {
                        method.setHeader(FilesConstants.X_CDN_REFERRER_ACL,
                                referrerAcl);
                    }

                    // User Agent ACL
                    if (userAgentACL != null) {
                        method.setHeader(FilesConstants.X_CDN_USER_AGENT_ACL,
                                userAgentACL);
                    }
                    FilesResponse response = new FilesResponse(
                            client.execute(method));

                    if (response.getStatusCode() == HttpStatus.SC_UNAUTHORIZED) {
                        method.abort();
                        if (login()) {
                            new HttpPost(cdnManagementURL + "/"
                                    + sanitizeForURI(name));
                            method.getParams().setIntParameter(
                                    "http.socket.timeout", connectionTimeOut);
                            method.setHeader(FilesConstants.X_AUTH_TOKEN,
                                    authToken);
                            // TTL
                            if (ttl > 0) {
                                method.setHeader(FilesConstants.X_CDN_TTL,
                                        Integer.toString(ttl));
                            }
                            // Enabled
                            method.setHeader(FilesConstants.X_CDN_ENABLED,
                                    Boolean.toString(enabled));
                            response = new FilesResponse(client.execute(method));
                        } else {
                            throw new FilesAuthorizationException(
                                    "Re-login failed",
                                    response.getResponseHeaders(),
                                    response.getStatusLine());
                        }
                    }

                    if (response.getStatusCode() == HttpStatus.SC_ACCEPTED) {
                        returnValue = response.getCdnUrl();
                    } else if (response.getStatusCode() == HttpStatus.SC_UNAUTHORIZED) {
                        logger.warn("Unauthorized access");
                        throw new FilesAuthorizationException(
                                "User not Authorized!",
                                response.getResponseHeaders(),
                                response.getStatusLine());
                    } else {
                        throw new FilesException("Unexpected Server Response",
                                response.getResponseHeaders(),
                                response.getStatusLine());
                    }
                } finally {
                    if (method != null) {
                        method.abort();
                    }
                }
            } else {
                throw new FilesInvalidNameException(name);
            }
        } else {
            throw new FilesAuthorizationException("You must be logged in",
                    null, null);
        }
        return returnValue;
    }

    /**
     * Gets current CDN sharing status of the container
     *
     * @param name The name of the container to enable
     * @return Information on the container
     * @throws IOException There was an IO error doing network communication
     * @throws HttpException There was an error with the http protocol
     * @throws FilesException There was an error talking to the CloudFiles
     * Server
     * @throws FilesNotFoundException The Container has never been CDN enabled
     */
    public FilesCDNContainer getCDNContainerInfo(String container)
            throws IOException, FilesNotFoundException, HttpException,
            FilesException {
        if (isLoggedin()) {
            if (isValidContainerName(container)) {
                HttpHead method = null;
                try {
                    method = new HttpHead(cdnManagementURL + "/"
                            + sanitizeForURI(container));
                    method.getParams().setIntParameter("http.socket.timeout",
                            connectionTimeOut);
                    method.setHeader(FilesConstants.X_AUTH_TOKEN, authToken);
                    FilesResponse response = new FilesResponse(
                            client.execute(method));

                    if (response.getStatusCode() == HttpStatus.SC_UNAUTHORIZED) {
                        method.abort();
                        if (login()) {
                            method = new HttpHead(cdnManagementURL + "/"
                                    + sanitizeForURI(container));
                            method.getParams().setIntParameter(
                                    "http.socket.timeout", connectionTimeOut);
                            method.setHeader(FilesConstants.X_AUTH_TOKEN,
                                    authToken);
                            response = new FilesResponse(client.execute(method));
                        } else {
                            throw new FilesAuthorizationException(
                                    "Re-login failed",
                                    response.getResponseHeaders(),
                                    response.getStatusLine());
                        }
                    }

                    if (response.getStatusCode() == HttpStatus.SC_NO_CONTENT) {
                        FilesCDNContainer result = new FilesCDNContainer(
                                response.getCdnUrl());
                        result.setName(container);
                        result.setSSLURL(response.getCdnSslUrl());
                        result.setStreamingURL(response.getCdnStreamingUrl());
                        for (Header hdr : response.getResponseHeaders()) {
                            String name = hdr.getName().toLowerCase();
                            if ("x-cdn-enabled".equals(name)) {
                                result.setEnabled(Boolean.valueOf(hdr
                                        .getValue()));
                            } else if ("x-log-retention".equals(name)) {
                                result.setRetainLogs(Boolean.valueOf(hdr
                                        .getValue()));
                            } else if ("x-ttl".equals(name)) {
                                result.setTtl(Integer.parseInt(hdr.getValue()));
                            } else if ("x-referrer-acl".equals(name)) {
                                result.setReferrerACL(hdr.getValue());
                            } else if ("x-user-agent-acl".equals(name)) {
                                result.setUserAgentACL(hdr.getValue());
                            }
                        }
                        return result;
                    } else if (response.getStatusCode() == HttpStatus.SC_UNAUTHORIZED) {
                        logger.warn("Unauthorized access");
                        throw new FilesAuthorizationException(
                                "User not Authorized!",
                                response.getResponseHeaders(),
                                response.getStatusLine());
                    } else if (response.getStatusCode() == HttpStatus.SC_NOT_FOUND) {
                        throw new FilesNotFoundException(
                                "Container is not CDN enabled",
                                response.getResponseHeaders(),
                                response.getStatusLine());
                    } else {
                        throw new FilesException(
                                "Unexpected result from server: ",
                                response.getResponseHeaders(),
                                response.getStatusLine());
                    }
                } finally {
                    if (method != null) {
                        method.abort();
                    }
                }
            } else {
                throw new FilesInvalidNameException(container);
            }
        } else {
            throw new FilesAuthorizationException("You must be logged in",
                    null, null);
        }
    }

    /**
     * Gets current CDN sharing status of the container
     *
     * @param name The name of the container to enable
     * @return Information on the container
     * @throws IOException There was an IO error doing network communication
     * @throws HttpException There was an error with the http protocol
     * @throws FilesException There was an error talking to the CloudFiles
     * Server
     * @throws FilesNotFoundException The Container has never been CDN enabled
     */
    public boolean isCDNEnabled(String container) throws IOException,
            HttpException, FilesException {
        if (isLoggedin()) {
            if (isValidContainerName(container)) {
                HttpHead method = null;
                try {
                    method = new HttpHead(cdnManagementURL + "/"
                            + sanitizeForURI(container));
                    method.getParams().setIntParameter("http.socket.timeout",
                            connectionTimeOut);
                    method.setHeader(FilesConstants.X_AUTH_TOKEN, authToken);
                    FilesResponse response = new FilesResponse(
                            client.execute(method));

                    if (response.getStatusCode() == HttpStatus.SC_UNAUTHORIZED) {
                        method.abort();
                        if (login()) {
                            method = new HttpHead(cdnManagementURL + "/"
                                    + sanitizeForURI(container));
                            method.getParams().setIntParameter(
                                    "http.socket.timeout", connectionTimeOut);
                            method.setHeader(FilesConstants.X_AUTH_TOKEN,
                                    authToken);
                            response = new FilesResponse(client.execute(method));
                        } else {
                            throw new FilesAuthorizationException(
                                    "Re-login failed",
                                    response.getResponseHeaders(),
                                    response.getStatusLine());
                        }
                    }

                    if (response.getStatusCode() == HttpStatus.SC_NO_CONTENT) {
                        for (Header hdr : response.getResponseHeaders()) {
                            String name = hdr.getName().toLowerCase();
                            if ("x-cdn-enabled".equals(name)) {
                                return Boolean.valueOf(hdr.getValue());
                            }
                        }
                        throw new FilesException(
                                "Server did not return X-CDN-Enabled header: ",
                                response.getResponseHeaders(),
                                response.getStatusLine());
                    } else if (response.getStatusCode() == HttpStatus.SC_UNAUTHORIZED) {
                        logger.warn("Unauthorized access");
                        throw new FilesAuthorizationException(
                                "User not Authorized!",
                                response.getResponseHeaders(),
                                response.getStatusLine());
                    } else if (response.getStatusCode() == HttpStatus.SC_NOT_FOUND) {
                        return false;
                    } else {
                        throw new FilesException(
                                "Unexpected result from server: ",
                                response.getResponseHeaders(),
                                response.getStatusLine());
                    }
                } finally {
                    if (method != null) {
                        method.abort();
                    }
                }
            } else {
                throw new FilesInvalidNameException(container);
            }
        } else {
            throw new FilesAuthorizationException("You must be logged in",
                    null, null);
        }
    }

