    static String inputStreamToString(InputStream stream, String encoding)
            throws IOException {
        char buffer[] = new char[4096];
        StringBuilder sb = new StringBuilder();
        InputStreamReader isr = new InputStreamReader(stream, "utf-8"); // For
        // now,
        // assume
        // utf-8
        // to
