		drawString(progressTitle, (width - TextRenderer.getTextLength(progressTitle)) / 2, height / 2 - 8 - 32, 0xffffff);
		drawString(progressText, (width - TextRenderer.getTextLength(progressText)) / 2, height / 2 - 8 + 16, 0xffffff);
