	 */
	public void setMessagingEnabled(boolean messagingEnabled) {
		this.messagingEnabled = messagingEnabled;
	}

	/**
	 * Get whether or not the user has accepted the Imgur Gallery terms.
	 * @return the acceptedGalleryTerms
	 */
