	 * @param acceptedGalleryTerms the acceptedGalleryTerms to set
	 */
	public void setAcceptedGalleryTerms(boolean acceptedGalleryTerms) {
		this.acceptedGalleryTerms = acceptedGalleryTerms;
	}

